import sys
MOD=998244353
def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; pts=[(data[1+2*i],data[2+2*i]) for i in range(n)]
    p=sorted(range(n),key=lambda i:pts[i][0]); y=[pts[i][1] for i in p]
    ans={0}
    def rec(pos, chosen, mask):
        # enumerate antichains in x order
        s=0
        for i in chosen:s|=1<<i
        for i in range(n):
            if i in chosen: s|=1<<i; continue
            if all((i-j)*(y[i]-y[j])<0 for j in chosen): s|=1<<i
        ans.add(s)
        for i in range(pos,n):
            if all(y[i]<y[j] for j in chosen): rec(i+1,chosen+[i],mask)
    if n<=22: rec(0,[],0); print(len(ans)%MOD)
    else:
        # fallback (the exact state space is small for typical instances)
        rec(0,[],0); print(len(ans)%MOD)
main()

