import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    it=iter(data); n=next(it); q=next(it)
    par=list(range(n)); sz=[1]*n; L=list(range(n)); R=list(range(n)); col=list(range(n)); cnt=[1]*(n+1)
    def find(x):
        while par[x]!=x:
            par[x]=par[par[x]]; x=par[x]
        return x
    def unite(a,b):
        a=find(a); b=find(b)
        if a==b:return a
        if sz[a]<sz[b]:a,b=b,a
        par[b]=a; sz[a]+=sz[b]
        L[a]=min(L[a],L[b]); R[a]=max(R[a],R[b])
        return a
    out=[]
    for _ in range(q):
        t=next(it)
        if t==1:
            x=next(it)-1; c=next(it)
            r=find(x); old=col[r]
            if old!=c:
                cnt[old]-=sz[r]; cnt[c]+=sz[r]; col[r]=c
            if L[r]>0:
                a=find(L[r]-1)
                if col[a]==c:r=unite(r,a)
            if R[r]+1<n:
                b=find(R[r]+1)
                if col[b]==c:r=unite(r,b)
        else:
            c=next(it); out.append(str(cnt[c]))
    print('\n'.join(out))
