import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    values = data[2:]
    machines = []
    upper = None
    for i in range(n):
        a, p, b, q = values[4*i:4*i+4]
        machines.append((a, p, b, q))
        # Even using only the better type, this bounds the capacity.
        limit = budget * max(a * q, b * p) // (p * q) + 1
        upper = limit if upper is None else min(upper, limit)

    def feasible(capacity):
        spent = 0
        for a, p, b, q in machines:
            best = ((capacity + a - 1) // a) * p

            # In an optimum either fewer than b S-machines or fewer than
            # a T-machines are used; enumerate both cases.
            for s in range(min(b - 1, capacity // a) + 1):
                remaining = max(0, capacity - s * a)
                cost = s * p + ((remaining + b - 1) // b) * q
                if cost < best:
                    best = cost
            for t in range(min(a - 1, capacity // b) + 1):
                remaining = max(0, capacity - t * b)
                cost = t * q + ((remaining + a - 1) // a) * p
                if cost < best:
                    best = cost

            spent += best
            if spent > budget:
                return False
        return True

    low, high = 0, upper
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == "__main__":
    solve()

