class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        comb = [[0] * (L + 1) for _ in range(L + 1)]
        comb[0][0] = 1
        for i in range(1, L + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        good = [False] * (L + 1)
        for bits in range(1, L + 1):
            value = bits
            steps = 0
            while value != 1 and steps <= k:
                value = value.bit_count()
                steps += 1
            good[bits] = value == 1 and steps <= k - 1

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                suffix_len = L - i - 1
                for suffix_ones in range(suffix_len + 1):
                    total_ones = prefix_ones + suffix_ones
                    if total_ones >= 1 and good[total_ones]:
                        answer = (answer + comb[suffix_len][suffix_ones]) % MOD
                prefix_ones += 1
        return answer

