    for i in range(n):
        for j,ch in enumerate(g[i]):
            if ch!='-':
                c=ord(ch)-97
                out[i][c].append(j)
                inc[j][c].append(i)
    inf=10**9
    dist=[inf]*(n*n)
    heap=[]
    for i in range(n):
        dist[i*n+i]=0
        heapq.heappush(heap,(0,i,i))
    for i in range(n):
        for j,ch in enumerate(g[i]):
            if ch!='-' and i!=j:
                p=i*n+j
                dist[p]=1
                heapq.heappush(heap,(1,i,j))
