import sys, heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    H, W, X = next(it), next(it), next(it)
    P, Q = next(it) - 1, next(it) - 1
    s = [[next(it) for _ in range(W)] for _ in range(H)]
    strength = s[P][Q]
    seen = [[False] * W for _ in range(H)]
    seen[P][Q] = True
    heap = []

    def add(i, j):
        if 0 <= i < H and 0 <= j < W and not seen[i][j]:
            seen[i][j] = True
            heapq.heappush(heap, (s[i][j], i, j))

    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        add(P + di, Q + dj)

    while heap:
        value, i, j = heap[0]
        if value * X >= strength:
            break
        heapq.heappop(heap)
        strength += value
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            add(i + di, j + dj)

    print(strength)

