from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        LIMIT = 10**15
        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = min(LIMIT, factorial[i - 1] * i)

        odd, even = (n + 1) // 2, n // 2
        available = [True] * (n + 1)
        result = []
        required = None

        def completions(ro, re, first_parity, length):
            if length == 0:
                return 1
            first_slots = (length + 1) // 2
            second_slots = length // 2
            if first_parity == 1:
                if ro != first_slots or re != second_slots:
                    return 0
            else:
                if re != first_slots or ro != second_slots:
                    return 0
            return min(LIMIT, factorial[ro] * factorial[re])

        for position in range(n):
            chosen = False
            for value in range(1, n + 1):
                if not available[value]:
                    continue
                parity = value & 1
                if required is not None and parity != required:
                    continue
                ro = odd - (parity == 1)
                re = even - (parity == 0)
                count = completions(ro, re, 1 - parity, n - position - 1)
                if count == 0:
                    continue
                if k > count:
                    k -= count
                else:
                    result.append(value)
                    available[value] = False
                    odd, even = ro, re
                    required = 1 - parity
                    chosen = True
                    break
            if not chosen:
                return []
        return result

