from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        LIM = 10**15
        fac = [1]*(n+1)
        for i in range(1,n+1):
            fac[i] = min(LIM, fac[i-1]*i)
        odd = (n+1)//2
        even = n//2
        rem = [True]*(n+1)
        ans = []
        req = None
        o, e = odd, even
        def ways(ro, re, need, length):
            if length == 0:
                return 1
            needcnt = (length+1)//2
            other = length//2
            if need == 1:
                if ro != needcnt or re != other:
                    return 0
            else:
                if re != needcnt or ro != other:
                    return 0
            return min(LIM, fac[ro]*fac[re])
        for pos in range(n):
            found = False
            for x in range(1,n+1):
                if not rem[x]:
                    continue
                p = x & 1
                if req is not None and p != req:
                    continue
                no, ne = o-(p==1), e-(p==0)
                nxt = 1-p
                cnt = ways(no, ne, nxt, n-pos-1)
                if cnt == 0:
                    continue
                if k > cnt:
                    k -= cnt
                else:
                    ans.append(x); rem[x]=False; o,e=no,ne; req=nxt; found=True; break
            if not found:
                return []
        return ans

