class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1 % k]
        for _ in range(1, n):
            powers.append(powers[-1] * 10 % k)
        coeff = []
        for i in range(m):
            j = n - 1 - i
            coeff.append(powers[i] if i == j else (powers[i] + powers[j]) % k)
        suf = [bytearray(k) for _ in range(m + 1)]
        suf[m][0] = 1
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            row, nxt = suf[i], suf[i + 1]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - d * c) % k]:
                        row[r] = 1
                        break
        ans = [0] * m
        rem = 0
        for i in range(m):
            lo = 1 if i == 0 else 0
            c = coeff[i]
            for d in range(9, lo - 1, -1):
                if suf[i + 1][(-rem - d * c) % k]:
                    ans[i] = d
                    rem = (rem + d * c) % k
                    break
        a = ''.join(map(str, ans))
        return a + a[:n // 2][::-1]

