class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] <= x:
                nxt[stack.pop()] = i
            stack.append(i)

        levels = n.bit_length()
        up = [array('i', nxt)]
        sums = [array('q', (nums[i] * (nxt[i] - i) for i in range(n)))]
        for _ in range(1, levels):
            pu, ps = up[-1], sums[-1]
            cu = array('i', [n]) * n
            cs = array('q', [0]) * n
            for i in range(n):
                j = pu[i]
                if j < n:
                    cu[i] = pu[j]
                    cs[i] = ps[i] + ps[j]
                else:
                    cs[i] = ps[i]
            up.append(cu)
            sums.append(cs)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        def cost(l, r):
            node = l
            total = 0
            for z in range(levels - 1, -1, -1):
                j = up[z][node]
                if j <= r:
                    total += sums[z][node]
                    node = j
            total += nums[node] * (r - node + 1)
            return total - (prefix[r + 1] - prefix[l])

        answer = 0
        for l in range(n):
            lo, hi = l, n
            while lo + 1 < hi:
                mid = (lo + hi) // 2
                if cost(l, mid) <= k:
                    lo = mid
                else:
                    hi = mid
            answer += lo - l + 1
        return answer

