from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, 2 + 2 * n, 2)]

    def compare(x, y):
        a, b = x
        c, d = y
        if a == 1:
            return 0 if c == 1 else -1
        if c == 1:
            return 1
        # Descending order of b/(a-1), using exact cross multiplication.
        left = b * (c - 1)
        right = d * (a - 1)
        return (right > left) - (right < left)

    funcs.sort(key=cmp_to_key(compare))
