import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    p = 3
    a = data[p:p+n]; p += n
    b = data[p:p+m]; p += m
    c = data[p:p+l]
    values = a + b + c
    k = len(values)
    all_mask = (1 << k) - 1
    takahashi = (1 << n) - 1
    aoki = ((1 << m) - 1) << n
    lower = []
    for x in values:
        mask = 0
        for j, y in enumerate(values):
            if y < x:
                mask |= 1 << j
        lower.append(mask)
    sys.setrecursionlimit(1000000)
    @lru_cache(maxsize=None)
    def winning(x, y, turn):
        hand = x if turn == 0 else y
        if hand == 0:
            return False
        table = all_mask ^ x ^ y
        other_turn = 1 - turn
        remaining = hand
        while remaining:
            bit = remaining & -remaining
            remaining ^= bit
            nx = x ^ bit if turn == 0 else x
            ny = y ^ bit if turn == 1 else y
            if not winning(nx, ny, other_turn):
                return True
            can_take = table & lower[bit.bit_length() - 1]
            while can_take:
                taken = can_take & -can_take
                can_take ^= taken
                if turn == 0:
                    if not winning(nx | taken, ny, other_turn):
                        return True
                else:
                    if not winning(nx, ny | taken, other_turn):
                        return True
        return False
    print("Takahashi" if winning(takahashi, aoki, 0) else "Aoki")

if __name__ == "__main__":
    main()

