from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        nonempty = [x for x in parts if x]
        if not nonempty:
            return 0

        def occurrences(t):
            m = len(t)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = prefix[j - 1]
                if t[i] == t[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = prefix[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        locations = [occurrences(t) for t in nonempty]
        if any(not a for a in locations):
            return -1

        n = len(s)
        best = n + 1
        first_len = len(nonempty[0])
        for start in locations[0]:
            position = start + first_len
            end = position
            possible = True
            for k in range(1, len(nonempty)):
                candidates = locations[k]
                index = bisect_left(candidates, position)
                if index == len(candidates):
                    possible = False
                    break
                end = candidates[index] + len(nonempty[k])
                position = end
            if possible:
                best = min(best, end - start)

        return -1 if best == n + 1 else best

