from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        postorder = []
        stack = [(0, False)]
        while stack:
            u, expanded = stack.pop()
            if expanded:
                postorder.append(u)
            else:
                stack.append((u, True))
                for v in reversed(children[u]):
                    stack.append((v, False))

        text = [s[u] for u in postorder]
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i-k] == text[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i-k-1] == text[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        size = [1] * n
        for u in postorder:
            if parent[u] != -1:
                size[parent[u]] += size[u]
        position = [0] * n
        for i, u in enumerate(postorder):
            position[u] = i

        answer = []
        for u in range(n):
            length = size[u]
            end = position[u]
            start = end - length + 1
            if length & 1:
                center = (start + end) // 2
                answer.append(odd[center] >= length // 2 + 1)
            else:
                center = (start + end + 1) // 2
                answer.append(even[center] >= length // 2)
        return answer

