import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        L = len(str(n))
        limit = 10 ** L
        prime = bytearray(b'\x01') * limit
        prime[0] = 0
        if limit > 1:
            prime[1] = 0
        i = 2
        while i * i < limit:
            if prime[i]:
                prime[i*i:limit:i] = b'\x00' * (((limit - 1 - i*i)//i) + 1)
            i += 1
        if prime[n] or prime[m]:
            return -1
        inf = 10**18
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]
        powers = [10**i for i in range(L)]
        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for p in powers:
                digit = (x // p) % 10
                if digit < 9:
                    y = x + p
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (cost + y, y))
                if digit > 0:
                    y = x - p
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (cost + y, y))
        return -1

