from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        next_row = [0] * n
        answer = 0
        for i in range(n - 2, 0, -1):
            row = [0] * n
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    row[j] = 1 + (next_row[j + 1] if j + 1 < n else 0)

            first_start = max(i + 1, 2 * i)
            first_condition = z[i] >= i
            if first_condition and first_start < n:
                answer += n - first_start

            second_end = (n + i) // 2
            for j in range(i + 1, second_end + 1):
                if row[j] >= j - i:
                    answer += 1
                    if first_condition and j >= first_start:
                        answer -= 1
            next_row = row

        return answer

