    def minCost(self, n: int, cost: List[List[int]]) -> int:
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]
        for i in range(1, n // 2):
            j = n - 1 - i
            ndp = [10**30] * 6
            for q, (a, b) in enumerate(states):
                best = 10**30
                for p, (pa, pb) in enumerate(states):
                    if pa != a and pb != b and dp[p] < best:
                        best = dp[p]
                ndp[q] = cost[i][a] + cost[j][b] + best
            dp = ndp
        return min(dp)
